package com.example.starter.baggage;

import java.util.List;

import jakarta.validation.constraints.NotBlank;

/**
 * 行李认领冻结 API 的请求与响应 DTO。
 * 所有时刻字段为 UTC ISO-8601 字符串；可空字段以 JSON null 表示，语义见各字段注释。
 */
public final class ClaimHoldDtos {

    private ClaimHoldDtos() {
    }

    /** 登记认领冻结请求。 */
    public record ClaimHoldRequest(
            @NotBlank(message = "requestId 不能为空") String requestId,
            @NotBlank(message = "bagTag 不能为空") String bagTag,
            @NotBlank(message = "claimKey 不能为空") String claimKey,
            @NotBlank(message = "passengerDigest 不能为空") String passengerDigest,
            @NotBlank(message = "reason 不能为空") String reason,
            @NotBlank(message = "operatorId 不能为空") String operatorId) {
    }

    /** 复核请求：由不同于登记客服的复核人核对乘客核验摘要。 */
    public record ClaimReviewRequest(
            @NotBlank(message = "requestId 不能为空") String requestId,
            @NotBlank(message = "passengerDigest 不能为空") String passengerDigest,
            @NotBlank(message = "reviewerId 不能为空") String reviewerId) {
    }

    /** 解除请求：第二次确认，原子恢复行李为可交接状态。 */
    public record ClaimReleaseRequest(
            @NotBlank(message = "requestId 不能为空") String requestId,
            @NotBlank(message = "operatorId 不能为空") String operatorId) {
    }

    /** 登记认领冻结响应：removedFromLegId 为本次移出的 OPEN 航段，未在清单中为 null。 */
    public record ClaimHoldResponse(String holdId, String bagTag, String claimKey,
                                    String status, String bagStatus, String reason,
                                    String operatorId, String previousStatus,
                                    String removedFromLegId, String heldAt) {
    }

    /** 复核响应。 */
    public record ClaimReviewResponse(String holdId, String bagTag, String status,
                                      String reviewerId, String reviewedAt) {
    }

    /** 解除响应：bagStatus 为恢复后的行李状态。 */
    public record ClaimReleaseResponse(String holdId, String bagTag, String status,
                                       String bagStatus, String operatorId, String releasedAt) {
    }

    /** 不可变链记录视图：字段、顺序与 null 语义稳定，prevHash 仅创世记录为 null。 */
    public record ChainRecordView(int seq, String eventType, String legId, String reason,
                                  String operatorId, String peerOperatorId, String eventTime,
                                  String prevHash, String recordHash) {
    }

    /** 冻结明细：含完整链记录，按 seq 升序。 */
    public record ClaimHoldDetail(String holdId, String bagTag, String claimKey, String status,
                                  String reason, String operatorId, String reviewerId,
                                  String previousStatus, String removedFromLegId,
                                  String heldAt, String reviewedAt, String releasedAt,
                                  List<ChainRecordView> chain) {
    }

    /** 单件行李的冻结历史响应：holds 按 heldAt、holdId 升序，holdCount 为实际数量。 */
    public record ClaimHoldHistoryResponse(String bagTag, int holdCount, List<ClaimHoldDetail> holds) {
    }

    /** 诊断列表项（不含链记录与乘客核验摘要）。 */
    public record ClaimHoldSummary(String holdId, String bagTag, String claimKey, String status,
                                   String operatorId, String reviewerId,
                                   String heldAt, String reviewedAt, String releasedAt) {
    }

    /**
     * 诊断查询响应：count 为实际命中数量；status/from/to 回显请求过滤条件，
     * 时间区间按左闭右开 [from, to) 解释，未提供的过滤条件为 null。
     */
    public record ClaimHoldListResponse(int count, String status, String from, String to,
                                        List<ClaimHoldSummary> items) {
    }
}

