package com.example.starter.baggage;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.time.OffsetDateTime;
import java.time.ZoneOffset;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.UUID;
import java.util.function.Supplier;

import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Service;

import com.example.starter.baggage.ClaimHoldDtos.ChainRecordView;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldDetail;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldHistoryResponse;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldListResponse;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldRequest;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldResponse;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldSummary;
import com.example.starter.baggage.ClaimHoldDtos.ClaimReleaseRequest;
import com.example.starter.baggage.ClaimHoldDtos.ClaimReleaseResponse;
import com.example.starter.baggage.ClaimHoldDtos.ClaimReviewRequest;
import com.example.starter.baggage.ClaimHoldDtos.ClaimReviewResponse;

/**
 * 行李认领冻结核心业务：登记冻结、复核、解除与明细/历史/诊断查询。
 * 所有写操作经 {@link IdempotencyService} 去重，业务变更、清单移出、链记录与去重记录原子提交；
 * 冻结与装载/封舱按航段行锁 + 行李行锁（先航段后行李）裁决提交顺序：
 * 封舱先提交则冻结 409，冻结先提交则装载 409（版本推进或行李状态冲突）。
 * 链记录只追加不更新，prev_hash 串联同一冻结内的记录哈希；查询均为只读，不改变状态。
 */
@Service
public class ClaimHoldService {

    private static final String LEG_SEALED = "SEALED";
    private static final String BAG_DELIVERED = "DELIVERED";
    private static final String BAG_CLAIM_HOLD = "CLAIM_HOLD";

    private static final String HOLD_ACTIVE = "ACTIVE";
    private static final String HOLD_REVIEWED = "REVIEWED";
    private static final String HOLD_RELEASED = "RELEASED";

    private static final String CHAIN_HOLD = "HOLD";
    private static final String CHAIN_MANIFEST_REMOVED = "MANIFEST_REMOVED";
    private static final String CHAIN_REVIEW = "REVIEW";
    private static final String CHAIN_RELEASE = "RELEASE";

    private static final String EVT_CLAIM_HOLD = "CLAIM_HOLD";
    private static final String EVT_CLAIM_RELEASED = "CLAIM_RELEASED";

    private static final RowMapper<HoldRow> HOLD_MAPPER = (rs, rowNum) -> new HoldRow(
            rs.getString("hold_id"), rs.getString("bag_tag"), rs.getString("claim_key"),
            rs.getString("passenger_digest"), rs.getString("reason"), rs.getString("operator_id"),
            rs.getString("reviewer_id"), rs.getString("status"), rs.getString("prev_bag_status"),
            rs.getString("removed_leg_id"), getInstant(rs, "held_at"),
            getInstant(rs, "reviewed_at"), getInstant(rs, "released_at"));

    private static final RowMapper<ChainRow> CHAIN_MAPPER = (rs, rowNum) -> new ChainRow(
            rs.getInt("seq"), rs.getString("event_type"), rs.getString("leg_id"),
            rs.getString("reason"), rs.getString("operator_id"), rs.getString("peer_operator_id"),
            getInstant(rs, "event_time"), rs.getString("prev_hash"), rs.getString("record_hash"));

    private static final RowMapper<BagRow> BAG_MAPPER = (rs, rowNum) -> new BagRow(
            rs.getString("bag_tag"), rs.getString("status"), rs.getString("loaded_leg_id"),
            rs.getString("current_location"));

    private static final RowMapper<LegRow> LEG_MAPPER = (rs, rowNum) -> new LegRow(
            rs.getString("leg_id"), rs.getString("status"), rs.getInt("version"));

    private final JdbcTemplate jdbcTemplate;
    private final IdempotencyService idempotencyService;
    /** 可控时钟，默认系统 UTC 时钟，测试可替换。 */
    private Supplier<Instant> clock = Instant::now;

    public ClaimHoldService(JdbcTemplate jdbcTemplate, IdempotencyService idempotencyService) {
        this.jdbcTemplate = jdbcTemplate;
        this.idempotencyService = idempotencyService;
    }

    /** 替换时钟（测试使用），所有登记时刻均取该时钟的 UTC 时刻。 */
    void setClock(Supplier<Instant> clock) {
        this.clock = clock;
    }

    /**
     * 登记认领冻结：未到达最终目的地的行李进入 CLAIM_HOLD。
     * 已 SEALED 航段清单内、已最终交付或已有生效冻结的行李返回 409；
     * 行李位于 OPEN 航段清单时，在同一事务内先移出清单（航段版本递增）并写入冻结历史。
     */
    public ClaimHoldResponse freeze(ClaimHoldRequest request) {
        FreezePayload payload = new FreezePayload(request.bagTag(), request.claimKey(),
                request.passengerDigest(), request.reason(), request.operatorId());
        return idempotencyService.execute(request.requestId(), "CLAIM_HOLD", 201,
                payload, ClaimHoldResponse.class, () -> doFreeze(request));
    }

    /** 复核：须由不同于登记客服的复核人核对乘客核验摘要，摘要不匹配返回 422。 */
    public ClaimReviewResponse review(String holdId, ClaimReviewRequest request) {
        ReviewPayload payload = new ReviewPayload(holdId, request.passengerDigest(), request.reviewerId());
        return idempotencyService.execute(request.requestId(), "CLAIM_REVIEW", 200,
                payload, ClaimReviewResponse.class, () -> doReview(holdId, request));
    }

    /** 解除：第二次确认，原子恢复行李为冻结前的可交接状态；冻结期间的旧装载请求不自动恢复。 */
    public ClaimReleaseResponse release(String holdId, ClaimReleaseRequest request) {
        ReleasePayload payload = new ReleasePayload(holdId, request.operatorId());
        return idempotencyService.execute(request.requestId(), "CLAIM_RELEASE", 200,
                payload, ClaimReleaseResponse.class, () -> doRelease(holdId, request));
    }

    /** 冻结明细查询（含链记录），只读。 */
    public ClaimHoldDetail getHold(String holdId) {
        HoldRow hold = findHold(holdId);
        if (hold == null) {
            throw ApiException.notFound("认领冻结不存在: " + holdId);
        }
        return toDetail(hold);
    }

    /** 单件行李的冻结历史查询：holds 按冻结时刻、holdId 升序，只读。 */
    public ClaimHoldHistoryResponse getBagHistory(String bagTag) {
        Integer bagCount = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM bag WHERE bag_tag = ?", Integer.class, bagTag);
        if (bagCount == null || bagCount == 0) {
            throw ApiException.notFound("行李不存在: " + bagTag);
        }
        List<HoldRow> holds = jdbcTemplate.query(holdSelect()
                        + " AND bag_tag = ? ORDER BY held_at, hold_id",
                HOLD_MAPPER, bagTag);
        List<ClaimHoldDetail> details = new ArrayList<>();
        for (HoldRow hold : holds) {
            details.add(toDetail(hold));
        }
        return new ClaimHoldHistoryResponse(bagTag, details.size(), details);
    }

    /**
     * 诊断列表查询：按状态与冻结时刻区间过滤，区间端点左闭右开 [from, to)。
     * 响应回显请求过滤条件并返回实际命中数量，只读。
     */
    public ClaimHoldListResponse listHolds(String status, String from, String to) {
        if (status != null && !List.of(HOLD_ACTIVE, HOLD_REVIEWED, HOLD_RELEASED).contains(status)) {
            throw new ApiException(HttpStatus.BAD_REQUEST,
                    "status 仅支持 ACTIVE/REVIEWED/RELEASED，实际为 " + status);
        }
        Instant fromInstant = parseInstant(from, "from");
        Instant toInstant = parseInstant(to, "to");
        if (fromInstant != null && toInstant != null && !fromInstant.isBefore(toInstant)) {
            throw new ApiException(HttpStatus.BAD_REQUEST,
                    "区间左端点 from 必须早于右端点 to（左闭右开）: from=" + from + ", to=" + to);
        }
        StringBuilder sql = new StringBuilder(
                "SELECT hold_id, bag_tag, claim_key, status, operator_id, reviewer_id,"
                        + " held_at, reviewed_at, released_at FROM claim_hold WHERE 1 = 1");
        List<Object> args = new ArrayList<>();
        if (status != null) {
            sql.append(" AND status = ?");
            args.add(status);
        }
        if (fromInstant != null) {
            sql.append(" AND held_at >= ?");
            args.add(OffsetDateTime.ofInstant(fromInstant, ZoneOffset.UTC));
        }
        if (toInstant != null) {
            sql.append(" AND held_at < ?");
            args.add(OffsetDateTime.ofInstant(toInstant, ZoneOffset.UTC));
        }
        sql.append(" ORDER BY held_at, hold_id");
        List<ClaimHoldSummary> items = jdbcTemplate.query(sql.toString(),
                (rs, rowNum) -> new ClaimHoldSummary(
                        rs.getString("hold_id"), rs.getString("bag_tag"), rs.getString("claim_key"),
                        rs.getString("status"), rs.getString("operator_id"), rs.getString("reviewer_id"),
                        getInstant(rs, "held_at").toString(),
                        toStringOrNull(getInstant(rs, "reviewed_at")),
                        toStringOrNull(getInstant(rs, "released_at"))),
                args.toArray());
        return new ClaimHoldListResponse(items.size(), status, from, to, items);
    }

    private ClaimHoldResponse doFreeze(ClaimHoldRequest request) {
        BagRow snapshot = findBag(request.bagTag());
        if (snapshot == null) {
            throw ApiException.notFound("行李不存在: " + request.bagTag());
        }
        // 先航段后行李的加锁顺序，与装载/封舱/到达一致，避免死锁并按提交顺序裁决
        String snapshotLegId = snapshot.loadedLegId();
        LegRow lockedLeg = null;
        if (snapshotLegId != null) {
            lockedLeg = lockLeg(snapshotLegId);
        }
        BagRow bag = lockBag(request.bagTag());
        if (snapshotLegId == null ? bag.loadedLegId() != null
                : !snapshotLegId.equals(bag.loadedLegId())) {
            if (bag.loadedLegId() == null) {
                // 并发到达已卸下：按未装载继续冻结
                lockedLeg = null;
            } else {
                // 并发装载改变了所在清单：未持有对应航段锁，失败不占键，调用方重试
                throw ApiException.conflict("行李 " + bag.bagTag() + " 装载状态并发变化，请重试冻结");
            }
        }
        if (BAG_DELIVERED.equals(bag.status())) {
            throw ApiException.conflict("行李 " + bag.bagTag() + " 已最终交付，不可冻结");
        }
        if (BAG_CLAIM_HOLD.equals(bag.status())) {
            throw ApiException.conflict("行李 " + bag.bagTag() + " 已存在生效冻结，不可重复冻结");
        }
        String removedLegId = null;
        if (bag.loadedLegId() != null) {
            if (LEG_SEALED.equals(lockedLeg.status())) {
                throw ApiException.conflict(
                        "行李 " + bag.bagTag() + " 所在航段 " + lockedLeg.legId() + " 已封舱，不可冻结");
            }
            // OPEN 航段清单：同事务先移出清单并推进航段版本
            removedLegId = bag.loadedLegId();
            jdbcTemplate.update("DELETE FROM load_record WHERE bag_tag = ?", bag.bagTag());
            jdbcTemplate.update("UPDATE leg SET version = version + 1 WHERE leg_id = ?", removedLegId);
        }
        String holdId = UUID.randomUUID().toString();
        Instant heldAt = clock.get();
        jdbcTemplate.update(
                "INSERT INTO claim_hold (hold_id, bag_tag, claim_key, passenger_digest, reason,"
                        + " operator_id, status, prev_bag_status, removed_leg_id, held_at)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                holdId, bag.bagTag(), request.claimKey(), request.passengerDigest(), request.reason(),
                request.operatorId(), HOLD_ACTIVE, bag.status(), removedLegId,
                OffsetDateTime.ofInstant(heldAt, ZoneOffset.UTC));
        jdbcTemplate.update(
                "UPDATE bag SET status = ?, loaded_leg_id = NULL WHERE bag_tag = ?",
                BAG_CLAIM_HOLD, bag.bagTag());
        appendChain(holdId, bag.bagTag(), 0, CHAIN_HOLD, null, request.reason(),
                request.operatorId(), null, heldAt, null);
        if (removedLegId != null) {
            appendChain(holdId, bag.bagTag(), 1, CHAIN_MANIFEST_REMOVED, removedLegId, null,
                    request.operatorId(), null, heldAt, lastChainHash(holdId));
        }
        insertBagEvent(bag.bagTag(), EVT_CLAIM_HOLD, removedLegId, bag.currentLocation(), heldAt);
        return new ClaimHoldResponse(holdId, bag.bagTag(), request.claimKey(), HOLD_ACTIVE,
                BAG_CLAIM_HOLD, request.reason(), request.operatorId(), bag.status(),
                removedLegId, heldAt.toString());
    }

    private ClaimReviewResponse doReview(String holdId, ClaimReviewRequest request) {
        HoldRow hold = lockHold(holdId);
        if (!HOLD_ACTIVE.equals(hold.status())) {
            throw ApiException.conflict("冻结 " + holdId + " 状态为 " + hold.status() + "，不可复核");
        }
        if (request.reviewerId().equals(hold.operatorId())) {
            throw ApiException.unprocessable(
                    "复核客服 " + request.reviewerId() + " 与登记客服相同，须由不同客服角色复核");
        }
        if (!request.passengerDigest().equals(hold.passengerDigest())) {
            throw ApiException.unprocessable("乘客核验摘要不匹配");
        }
        Instant reviewedAt = clock.get();
        jdbcTemplate.update(
                "UPDATE claim_hold SET status = ?, reviewer_id = ?, reviewed_at = ? WHERE hold_id = ?",
                HOLD_REVIEWED, request.reviewerId(),
                OffsetDateTime.ofInstant(reviewedAt, ZoneOffset.UTC), holdId);
        appendChain(holdId, hold.bagTag(), nextChainSeq(holdId), CHAIN_REVIEW, null, null,
                request.reviewerId(), hold.operatorId(), reviewedAt, lastChainHash(holdId));
        return new ClaimReviewResponse(holdId, hold.bagTag(), HOLD_REVIEWED,
                request.reviewerId(), reviewedAt.toString());
    }

    private ClaimReleaseResponse doRelease(String holdId, ClaimReleaseRequest request) {
        HoldRow hold = lockHold(holdId);
        if (HOLD_RELEASED.equals(hold.status())) {
            throw ApiException.conflict("冻结 " + holdId + " 已解除，不得重复解除");
        }
        if (!HOLD_REVIEWED.equals(hold.status())) {
            throw ApiException.conflict("冻结 " + holdId + " 状态为 " + hold.status() + "，须先复核再解除");
        }
        BagRow bag = lockBag(hold.bagTag());
        if (bag == null || !BAG_CLAIM_HOLD.equals(bag.status())) {
            throw ApiException.conflict("行李 " + hold.bagTag() + " 当前不在冻结状态，无法解除");
        }
        Instant releasedAt = clock.get();
        jdbcTemplate.update(
                "UPDATE claim_hold SET status = ?, released_at = ? WHERE hold_id = ?",
                HOLD_RELEASED, OffsetDateTime.ofInstant(releasedAt, ZoneOffset.UTC), holdId);
        jdbcTemplate.update("UPDATE bag SET status = ? WHERE bag_tag = ?",
                hold.prevBagStatus(), hold.bagTag());
        appendChain(holdId, hold.bagTag(), nextChainSeq(holdId), CHAIN_RELEASE, null, null,
                request.operatorId(), hold.reviewerId(), releasedAt, lastChainHash(holdId));
        insertBagEvent(hold.bagTag(), EVT_CLAIM_RELEASED, null, bag.currentLocation(), releasedAt);
        return new ClaimReleaseResponse(holdId, hold.bagTag(), HOLD_RELEASED,
                hold.prevBagStatus(), request.operatorId(), releasedAt.toString());
    }

    /** 追加一条不可变链记录：record_hash 覆盖全部业务字段与 prev_hash。 */
    private void appendChain(String holdId, String bagTag, int seq, String eventType,
                             String legId, String reason, String operatorId, String peerOperatorId,
                             Instant eventTime, String prevHash) {
        String recordHash = chainHash(holdId, bagTag, seq, eventType, legId, reason,
                operatorId, peerOperatorId, eventTime, prevHash);
        jdbcTemplate.update(
                "INSERT INTO claim_hold_chain (hold_id, bag_tag, seq, event_type, leg_id, reason,"
                        + " operator_id, peer_operator_id, event_time, prev_hash, record_hash)"
                        + " VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)",
                holdId, bagTag, seq, eventType, legId, reason, operatorId, peerOperatorId,
                OffsetDateTime.ofInstant(eventTime, ZoneOffset.UTC), prevHash, recordHash);
    }

    private static String chainHash(String holdId, String bagTag, int seq, String eventType,
                                    String legId, String reason, String operatorId,
                                    String peerOperatorId, Instant eventTime, String prevHash) {
        String canonical = String.join("|", holdId, bagTag, String.valueOf(seq), eventType,
                nullMarker(legId), nullMarker(reason), operatorId, nullMarker(peerOperatorId),
                eventTime.toString(), nullMarker(prevHash));
        try {
            MessageDigest digest = MessageDigest.getInstance("SHA-256");
            return HexFormat.of().formatHex(digest.digest(canonical.getBytes(StandardCharsets.UTF_8)));
        } catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 不可用", ex);
        }
    }

    private static String nullMarker(String value) {
        return value == null ? "<null>" : value;
    }

    private int nextChainSeq(String holdId) {
        Integer maxSeq = jdbcTemplate.queryForObject(
                "SELECT MAX(seq) FROM claim_hold_chain WHERE hold_id = ?", Integer.class, holdId);
        return maxSeq == null ? 0 : maxSeq + 1;
    }

    private String lastChainHash(String holdId) {
        List<String> hashes = jdbcTemplate.query(
                "SELECT record_hash FROM claim_hold_chain WHERE hold_id = ? ORDER BY seq DESC LIMIT 1",
                (rs, rowNum) -> rs.getString("record_hash"), holdId);
        return hashes.isEmpty() ? null : hashes.get(0);
    }

    /** 追加行李轨迹事件，seq 按该行李已有事件数递增。 */
    private void insertBagEvent(String bagTag, String eventType, String legId, String location,
                                Instant eventTime) {
        Integer maxSeq = jdbcTemplate.queryForObject(
                "SELECT MAX(seq) FROM bag_event WHERE bag_tag = ?", Integer.class, bagTag);
        int nextSeq = maxSeq == null ? 0 : maxSeq + 1;
        jdbcTemplate.update(
                "INSERT INTO bag_event (bag_tag, seq, event_type, leg_id, location, event_time)"
                        + " VALUES (?, ?, ?, ?, ?, ?)",
                bagTag, nextSeq, eventType, legId, location,
                OffsetDateTime.ofInstant(eventTime, ZoneOffset.UTC));
    }

    private ClaimHoldDetail toDetail(HoldRow hold) {
        List<ChainRecordView> chain = jdbcTemplate.query(
                "SELECT seq, event_type, leg_id, reason, operator_id, peer_operator_id,"
                        + " event_time, prev_hash, record_hash FROM claim_hold_chain"
                        + " WHERE hold_id = ? ORDER BY seq",
                (rs, rowNum) -> {
                    ChainRow row = CHAIN_MAPPER.mapRow(rs, rowNum);
                    return new ChainRecordView(row.seq(), row.eventType(), row.legId(), row.reason(),
                            row.operatorId(), row.peerOperatorId(), row.eventTime().toString(),
                            row.prevHash(), row.recordHash());
                }, hold.holdId());
        return new ClaimHoldDetail(hold.holdId(), hold.bagTag(), hold.claimKey(), hold.status(),
                hold.reason(), hold.operatorId(), hold.reviewerId(), hold.prevBagStatus(),
                hold.removedLegId(), hold.heldAt().toString(), toStringOrNull(hold.reviewedAt()),
                toStringOrNull(hold.releasedAt()), chain);
    }

    private HoldRow findHold(String holdId) {
        List<HoldRow> rows = jdbcTemplate.query(holdSelect() + " AND hold_id = ?",
                HOLD_MAPPER, holdId);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private HoldRow lockHold(String holdId) {
        List<HoldRow> rows = jdbcTemplate.query(holdSelect() + " AND hold_id = ? FOR UPDATE",
                HOLD_MAPPER, holdId);
        if (rows.isEmpty()) {
            throw ApiException.notFound("认领冻结不存在: " + holdId);
        }
        return rows.get(0);
    }

    private static String holdSelect() {
        return "SELECT hold_id, bag_tag, claim_key, passenger_digest, reason, operator_id,"
                + " reviewer_id, status, prev_bag_status, removed_leg_id, held_at, reviewed_at,"
                + " released_at FROM claim_hold WHERE 1 = 1";
    }

    private BagRow findBag(String bagTag) {
        List<BagRow> rows = jdbcTemplate.query(bagSelect(false), BAG_MAPPER, bagTag);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private BagRow lockBag(String bagTag) {
        List<BagRow> rows = jdbcTemplate.query(bagSelect(true), BAG_MAPPER, bagTag);
        return rows.isEmpty() ? null : rows.get(0);
    }

    private static String bagSelect(boolean forUpdate) {
        return "SELECT bag_tag, status, loaded_leg_id, current_location FROM bag WHERE bag_tag = ?"
                + (forUpdate ? " FOR UPDATE" : "");
    }

    private LegRow lockLeg(String legId) {
        List<LegRow> rows = jdbcTemplate.query(
                "SELECT leg_id, status, version FROM leg WHERE leg_id = ? FOR UPDATE",
                LEG_MAPPER, legId);
        if (rows.isEmpty()) {
            throw ApiException.notFound("航段不存在: " + legId);
        }
        return rows.get(0);
    }

    /** 解析 ISO-8601 UTC 时刻查询参数，非法格式返回 400。 */
    private static Instant parseInstant(String value, String paramName) {
        if (value == null) {
            return null;
        }
        try {
            return Instant.parse(value);
        } catch (Exception ex) {
            throw new ApiException(HttpStatus.BAD_REQUEST,
                    "查询参数 " + paramName + " 不是合法的 UTC 时刻（ISO-8601）: " + value);
        }
    }

    private static Instant getInstant(java.sql.ResultSet rs, String column) throws java.sql.SQLException {
        OffsetDateTime value = rs.getObject(column, OffsetDateTime.class);
        return value == null ? null : value.toInstant();
    }

    private static String toStringOrNull(Instant value) {
        return value == null ? null : value.toString();
    }

    private record HoldRow(String holdId, String bagTag, String claimKey, String passengerDigest,
                           String reason, String operatorId, String reviewerId, String status,
                           String prevBagStatus, String removedLegId, Instant heldAt,
                           Instant reviewedAt, Instant releasedAt) {
    }

    private record ChainRow(int seq, String eventType, String legId, String reason,
                            String operatorId, String peerOperatorId, Instant eventTime,
                            String prevHash, String recordHash) {
    }

    private record BagRow(String bagTag, String status, String loadedLegId, String currentLocation) {
    }

    private record LegRow(String legId, String status, int version) {
    }

    /** 冻结幂等摘要参数。 */
    private record FreezePayload(String bagTag, String claimKey, String passengerDigest,
                                 String reason, String operatorId) {
    }

    /** 复核幂等摘要参数。 */
    private record ReviewPayload(String holdId, String passengerDigest, String reviewerId) {
    }

    /** 解除幂等摘要参数。 */
    private record ReleasePayload(String holdId, String operatorId) {
    }
}

