                .andExpect(jsonPath("$.status").value("CLAIM_HOLD"));
    }

    @Test
    void chainRecords_areImmutableAcrossReviewAndRelease() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());
        load("LEG1", 1, List.of("BAG1")).andExpect(status().isOk());
        MvcResult frozen = freeze("BAG1", "CLAIM-1", "DIGEST-1", "原因", "CS_A")
                .andExpect(status().isCreated()).andReturn();
        String holdId = holdIdOf(frozen);

        JsonNode before = objectMapper.readTree(mockMvc.perform(get("/api/claim-holds/" + holdId))
                .andReturn().getResponse().getContentAsString()).get("chain");
        assertThat(before).hasSize(2);

        review(holdId, "DIGEST-1", "CS_B").andExpect(status().isOk());
        release(holdId, "CS_B").andExpect(status().isOk());

        JsonNode after = objectMapper.readTree(mockMvc.perform(get("/api/claim-holds/" + holdId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.chain", hasSize(4)))
                .andExpect(jsonPath("$.chain[2].eventType").value("REVIEW"))
                .andExpect(jsonPath("$.chain[2].operatorId").value("CS_B"))
                .andExpect(jsonPath("$.chain[2].peerOperatorId").value("CS_A"))
                .andExpect(jsonPath("$.chain[3].eventType").value("RELEASE"))
                .andExpect(jsonPath("$.chain[3].peerOperatorId").value("CS_B"))
                .andReturn().getResponse().getContentAsString()).get("chain");

        // 冻结阶段的链记录不被后续操作改写
        assertThat(after.get(0)).isEqualTo(before.get(0));
        assertThat(after.get(1)).isEqualTo(before.get(1));
        // 哈希链完整：每条记录的 prevHash 等于前一条 recordHash
        for (int i = 1; i < after.size(); i++) {
            assertThat(after.get(i).get("prevHash").asText())
                    .isEqualTo(after.get(i - 1).get("recordHash").asText());
        }
    }

