package com.example.starter.baggage;

import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.UUID;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.MvcResult;
import org.springframework.test.web.servlet.ResultActions;

import static org.assertj.core.api.Assertions.assertThat;
import static org.hamcrest.Matchers.contains;
import static org.hamcrest.Matchers.hasSize;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

/**
 * 行李认领冻结 API 测试：覆盖登记冻结主流程（OPEN 清单移出）、失败分支
 * （已封舱/已交付/重复冻结/摘要 mismatch/同客服复核/未复核解除）、
 * 幂等边界、冻结期间旧装载请求不自动恢复、明细/历史/诊断查询与链记录稳定性。
 * 全部基于 H2 MySQL 兼容模式真实数据库，不使用 mock。
 */
@SpringBootTest
@AutoConfigureMockMvc
class ClaimHoldApiTest {

    private static final Instant T_HOLD = Instant.parse("2026-09-27T01:00:00Z");
    private static final Instant T_HOLD_2 = Instant.parse("2026-09-27T02:00:00Z");
    private static final Instant T_REVIEW = Instant.parse("2026-09-27T03:00:00Z");
    private static final Instant T_RELEASE = Instant.parse("2026-09-27T04:00:00Z");

    @Autowired
    private MockMvc mockMvc;

    @Autowired
    private ObjectMapper objectMapper;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    @Autowired
    private BaggageService baggageService;

    @Autowired
    private ClaimHoldService claimHoldService;

    @BeforeEach
    void cleanDatabase() {
        jdbcTemplate.update("DELETE FROM claim_hold_chain");
        jdbcTemplate.update("DELETE FROM claim_hold");
        jdbcTemplate.update("DELETE FROM bag_event");
        jdbcTemplate.update("DELETE FROM load_record");
        jdbcTemplate.update("DELETE FROM bag_itinerary");
        jdbcTemplate.update("DELETE FROM bag");
        jdbcTemplate.update("DELETE FROM leg");
        jdbcTemplate.update("DELETE FROM request_log");
        baggageService.setClock(Instant::now);
        claimHoldService.setClock(Instant::now);
    }

    @Test
    void freezeOnOpenManifest_removesFromListBlocksLoadAndRestoresAfterRelease() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());
        load("LEG1", 1, List.of("BAG1")).andExpect(status().isOk());

        claimHoldService.setClock(() -> T_HOLD);
        MvcResult frozen = freeze("BAG1", "CLAIM-1", "DIGEST-1", "乘客认领争议", "CS_A")
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.bagTag").value("BAG1"))
                .andExpect(jsonPath("$.claimKey").value("CLAIM-1"))
                .andExpect(jsonPath("$.status").value("ACTIVE"))
                .andExpect(jsonPath("$.bagStatus").value("CLAIM_HOLD"))
                .andExpect(jsonPath("$.previousStatus").value("IN_TRANSIT"))
                .andExpect(jsonPath("$.removedFromLegId").value("LEG1"))
                .andExpect(jsonPath("$.heldAt").value(T_HOLD.toString()))
                .andReturn();
        String holdId = holdIdOf(frozen);

        // 同一事务内移出 OPEN 清单：load_record 清空、航段版本推进、行李转 CLAIM_HOLD
        Integer loadRecords = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
        assertThat(loadRecords).isZero();
        mockMvc.perform(get("/api/legs/LEG1/manifest"))
                .andExpect(jsonPath("$.status").value("OPEN"))
                .andExpect(jsonPath("$.version").value(3));
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.status").value("CLAIM_HOLD"))
                .andExpect(jsonPath("$.loadedLegId").doesNotExist())
                .andExpect(jsonPath("$.events[*].eventType",
                        contains("REGISTERED", "LOADED", "CLAIM_HOLD")));

        // 明细：链记录 HOLD + MANIFEST_REMOVED，创世记录 prevHash 为 null，哈希串联
        MvcResult detail = mockMvc.perform(get("/api/claim-holds/" + holdId))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.reviewerId").doesNotExist())
                .andExpect(jsonPath("$.reviewedAt").doesNotExist())
                .andExpect(jsonPath("$.releasedAt").doesNotExist())
                .andExpect(jsonPath("$.chain", hasSize(2)))
                .andExpect(jsonPath("$.chain[0].seq").value(0))
                .andExpect(jsonPath("$.chain[0].eventType").value("HOLD"))
                .andExpect(jsonPath("$.chain[0].reason").value("乘客认领争议"))
                .andExpect(jsonPath("$.chain[0].operatorId").value("CS_A"))
                .andExpect(jsonPath("$.chain[0].peerOperatorId").doesNotExist())
                .andExpect(jsonPath("$.chain[0].legId").doesNotExist())
                .andExpect(jsonPath("$.chain[0].prevHash").doesNotExist())
                .andExpect(jsonPath("$.chain[0].eventTime").value(T_HOLD.toString()))
                .andExpect(jsonPath("$.chain[1].seq").value(1))
                .andExpect(jsonPath("$.chain[1].eventType").value("MANIFEST_REMOVED"))
                .andExpect(jsonPath("$.chain[1].legId").value("LEG1"))
                .andExpect(jsonPath("$.chain[1].reason").doesNotExist())
                .andReturn();
        JsonNode chain = objectMapper.readTree(detail.getResponse().getContentAsString()).get("chain");
        assertThat(chain.get(0).get("recordHash").asText()).isNotBlank();
        assertThat(chain.get(1).get("prevHash").asText())
                .isEqualTo(chain.get(0).get("recordHash").asText());

        // 冻结期间禁止装载（409）、禁止未复核解除（409）
        load("LEG1", 3, List.of("BAG1")).andExpect(status().isConflict());
        release(holdId, "CS_B").andExpect(status().isConflict());

        // 复核：摘要不匹配 422、同客服 422、不同客服且摘要匹配 200
        review(holdId, "WRONG-DIGEST", "CS_B").andExpect(status().isUnprocessableEntity());
        review(holdId, "DIGEST-1", "CS_A").andExpect(status().isUnprocessableEntity());
        claimHoldService.setClock(() -> T_REVIEW);
        review(holdId, "DIGEST-1", "CS_B").andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("REVIEWED"))
                .andExpect(jsonPath("$.reviewerId").value("CS_B"))
                .andExpect(jsonPath("$.reviewedAt").value(T_REVIEW.toString()));

        // 解除：第二次确认原子恢复为可交接状态
        claimHoldService.setClock(() -> T_RELEASE);
        release(holdId, "CS_B").andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("RELEASED"))
                .andExpect(jsonPath("$.bagStatus").value("IN_TRANSIT"))
                .andExpect(jsonPath("$.releasedAt").value(T_RELEASE.toString()));
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.status").value("IN_TRANSIT"))
                .andExpect(jsonPath("$.loadedLegId").doesNotExist())
                .andExpect(jsonPath("$.events[*].eventType",
                        contains("REGISTERED", "LOADED", "CLAIM_HOLD", "CLAIM_RELEASED")));

        // 解除后须按当前版本重提装载
        load("LEG1", 3, List.of("BAG1")).andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(4));
    }

    @Test
    void freezeWithoutManifest_removedLegIsNull() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());

        MvcResult frozen = freeze("BAG1", "CLAIM-1", "DIGEST-1", "认领待核验", "CS_A")
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.removedFromLegId").doesNotExist())
                .andReturn();
        String holdId = holdIdOf(frozen);

        mockMvc.perform(get("/api/claim-holds/" + holdId))
                .andExpect(jsonPath("$.removedFromLegId").doesNotExist())
                .andExpect(jsonPath("$.chain", hasSize(1)))
                .andExpect(jsonPath("$.chain[0].eventType").value("HOLD"));
        // 未装载行李冻结不影响航段版本
        mockMvc.perform(get("/api/legs/LEG1/manifest"))
                .andExpect(jsonPath("$.version").value(1));
    }

    @Test
    void freeze_rejectsSealedDeliveredDuplicateAndUnknown() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());
        load("LEG1", 1, List.of("BAG1")).andExpect(status().isOk());
        seal("LEG1", 2).andExpect(status().isOk());

        // 已 SEALED 航段清单内行李不可冻结：409 且查询不到半成品
        freeze("BAG1", "CLAIM-1", "DIGEST-1", "原因", "CS_A").andExpect(status().isConflict());
        assertThat(countRows("claim_hold")).isZero();
        assertThat(countRows("claim_hold_chain")).isZero();
        Integer loadRecords = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
        assertThat(loadRecords).isEqualTo(1);
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.status").value("IN_TRANSIT"))
                .andExpect(jsonPath("$.loadedLegId").value("LEG1"));

        // 已最终交付行李不可冻结
        arrive("LEG1", List.of("BAG1")).andExpect(status().isOk());
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.status").value("DELIVERED"));
        freeze("BAG1", "CLAIM-1", "DIGEST-1", "原因", "CS_A").andExpect(status().isConflict());

        // 行李不存在 -> 404
        freeze("BAG_MISSING", "CLAIM-1", "DIGEST-1", "原因", "CS_A")
                .andExpect(status().isNotFound());

        // 同一行李同时只能一个生效冻结
        registerBag("BAG2", List.of("LEG1")).andExpect(status().isCreated());
        freeze("BAG2", "CLAIM-2", "DIGEST-2", "原因", "CS_A").andExpect(status().isCreated());
        freeze("BAG2", "CLAIM-3", "DIGEST-2", "原因", "CS_B").andExpect(status().isConflict());
        assertThat(countRows("claim_hold")).isEqualTo(1);
    }

    @Test
    void freezeOnShortUnloaded_blocksRecoverUntilRelease() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerLeg("LEG2", "SHA", "CAN").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1", "LEG2")).andExpect(status().isCreated());
        load("LEG1", 1, List.of("BAG1")).andExpect(status().isOk());
        seal("LEG1", 2).andExpect(status().isOk());
        diffArrive("LEG1", 3, List.of()).andExpect(status().isOk());

        MvcResult frozen = freeze("BAG1", "CLAIM-1", "DIGEST-1", "短卸认领", "CS_A")
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.previousStatus").value("SHORT_UNLOADED"))
                .andExpect(jsonPath("$.removedFromLegId").doesNotExist())
                .andReturn();
        String holdId = holdIdOf(frozen);

        // 冻结期间禁止补到确认
        recover("BAG1", "LEG1", "SHA").andExpect(status().isConflict());

        review(holdId, "DIGEST-1", "CS_B").andExpect(status().isOk());
        release(holdId, "CS_B").andExpect(status().isOk())
                .andExpect(jsonPath("$.bagStatus").value("SHORT_UNLOADED"));

        // 解除后恢复短卸状态，可正常补到
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.status").value("SHORT_UNLOADED"))
                .andExpect(jsonPath("$.shortLegId").value("LEG1"));
        recover("BAG1", "LEG1", "SHA").andExpect(status().isOk())
                .andExpect(jsonPath("$.status").value("RECOVERED"));
    }

    @Test
    void staleLoadRequestDuringHold_isNotAutoResumedAfterRelease() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());
        load("LEG1", 1, List.of("BAG1")).andExpect(status().isOk());
        MvcResult frozen = freeze("BAG1", "CLAIM-1", "DIGEST-1", "原因", "CS_A")
                .andExpect(status().isCreated()).andReturn();
        String holdId = holdIdOf(frozen);

        // 冻结期间提交的旧装载请求：409 且失败不占键
        String staleRequestId = UUID.randomUUID().toString();
        Map<String, Object> staleLoad = Map.of("requestId", staleRequestId,
                "expectedVersion", 3, "bagTags", List.of("BAG1"));
        postJson("/api/legs/LEG1/load", staleLoad).andExpect(status().isConflict());

        review(holdId, "DIGEST-1", "CS_B").andExpect(status().isOk());
        release(holdId, "CS_B").andExpect(status().isOk());

        // 旧装载请求不自动恢复：行李未装载、清单为空
        mockMvc.perform(get("/api/bags/BAG1/trace"))
                .andExpect(jsonPath("$.loadedLegId").doesNotExist());
        Integer loadRecords = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
        assertThat(loadRecords).isZero();

        // 必须重提并按当前容量（版本）校验：同 requestId 重提成功
        postJson("/api/legs/LEG1/load", staleLoad).andExpect(status().isOk())
                .andExpect(jsonPath("$.version").value(4));
    }

    @Test
    void idempotency_freezeReplayConflictAndFailureNotOccupyingKey() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());

        String requestId = UUID.randomUUID().toString();
        Map<String, Object> body = Map.of("requestId", requestId, "bagTag", "BAG1",
                "claimKey", "CLAIM-1", "passengerDigest", "DIGEST-1",
                "reason", "原因", "operatorId", "CS_A");
        MvcResult first = postJson("/api/bags/claim-holds", body)
                .andExpect(status().isCreated()).andReturn();
        // 同键同参重放：返回同一 holdId，不产生第二条冻结
        postJson("/api/bags/claim-holds", body).andExpect(status().isCreated())
                .andExpect(jsonPath("$.holdId").value(holdIdOf(first)));
        assertThat(countRows("claim_hold")).isEqualTo(1);
        assertThat(countRows("claim_hold_chain")).isEqualTo(1);

        // 同键异参 -> 409
        postJson("/api/bags/claim-holds", Map.of("requestId", requestId, "bagTag", "BAG1",
                "claimKey", "CLAIM-1", "passengerDigest", "DIGEST-1",
                "reason", "另一个原因", "operatorId", "CS_A")).andExpect(status().isConflict());

        // 失败不占键：先以不存在的行李失败（404），再同键成功
        String retryKey = UUID.randomUUID().toString();
        postJson("/api/bags/claim-holds", Map.of("requestId", retryKey, "bagTag", "BAG_MISSING",
                "claimKey", "CLAIM-2", "passengerDigest", "D", "reason", "R", "operatorId", "CS_A"))
                .andExpect(status().isNotFound());
        registerBag("BAG2", List.of("LEG1")).andExpect(status().isCreated());
        postJson("/api/bags/claim-holds", Map.of("requestId", retryKey, "bagTag", "BAG2",
                "claimKey", "CLAIM-2", "passengerDigest", "D", "reason", "R", "operatorId", "CS_A"))
                .andExpect(status().isCreated());
    }

    @Test
    void idempotency_reviewAndReleaseReplayAndDoubleReleaseRejected() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());
        MvcResult frozen = freeze("BAG1", "CLAIM-1", "DIGEST-1", "原因", "CS_A")
                .andExpect(status().isCreated()).andReturn();
        String holdId = holdIdOf(frozen);

        // 复核重放：同键同参返回原结果，链记录不重复
        String reviewKey = UUID.randomUUID().toString();
        Map<String, Object> reviewBody = Map.of("requestId", reviewKey,
                "passengerDigest", "DIGEST-1", "reviewerId", "CS_B");
        postJson("/api/claim-holds/" + holdId + "/review", reviewBody).andExpect(status().isOk());
        postJson("/api/claim-holds/" + holdId + "/review", reviewBody).andExpect(status().isOk());
        mockMvc.perform(get("/api/claim-holds/" + holdId))
                .andExpect(jsonPath("$.chain", hasSize(2)));
        // 复核后再次以新键复核 -> 409
        review(holdId, "DIGEST-1", "CS_C").andExpect(status().isConflict());

        // 解除重放：同键同参返回原结果；新键重复解除 -> 409
        String releaseKey = UUID.randomUUID().toString();
        Map<String, Object> releaseBody = Map.of("requestId", releaseKey, "operatorId", "CS_B");
        postJson("/api/claim-holds/" + holdId + "/release", releaseBody).andExpect(status().isOk());
        postJson("/api/claim-holds/" + holdId + "/release", releaseBody).andExpect(status().isOk());
        release(holdId, "CS_C").andExpect(status().isConflict());
        mockMvc.perform(get("/api/claim-holds/" + holdId))
                .andExpect(jsonPath("$.chain", hasSize(3)))
                .andExpect(jsonPath("$.status").value("RELEASED"));
    }

    @Test
    void queries_detailHistoryAndDiagnosticWithHalfOpenInterval() throws Exception {
        registerLeg("LEG1", "PEK", "SHA").andExpect(status().isCreated());
        registerBag("BAG1", List.of("LEG1")).andExpect(status().isCreated());
        registerBag("BAG2", List.of("LEG1")).andExpect(status().isCreated());

        claimHoldService.setClock(() -> T_HOLD);
        MvcResult first = freeze("BAG1", "CLAIM-1", "DIGEST-1", "原因一", "CS_A")
                .andExpect(status().isCreated()).andReturn();
        String holdId1 = holdIdOf(first);
        claimHoldService.setClock(() -> T_HOLD_2);
        freeze("BAG2", "CLAIM-2", "DIGEST-2", "原因二", "CS_A").andExpect(status().isCreated());

        // 明细查询
        mockMvc.perform(get("/api/claim-holds/" + holdId1))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.bagTag").value("BAG1"))
                .andExpect(jsonPath("$.heldAt").value(T_HOLD.toString()));
        mockMvc.perform(get("/api/claim-holds/HOLD_MISSING")).andExpect(status().isNotFound());

        // 历史查询
        mockMvc.perform(get("/api/bags/BAG1/claim-holds"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.holdCount").value(1))
                .andExpect(jsonPath("$.holds", hasSize(1)))
                .andExpect(jsonPath("$.holds[0].holdId").value(holdId1));
        mockMvc.perform(get("/api/bags/NOPE/claim-holds")).andExpect(status().isNotFound());

        // 诊断查询：区间端点左闭右开 [from, to)，count 返回实际命中数
        mockMvc.perform(get("/api/claim-holds"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.count").value(2))
                .andExpect(jsonPath("$.items", hasSize(2)));
        mockMvc.perform(get("/api/claim-holds")
                        .param("from", T_HOLD.toString()).param("to", T_HOLD_2.toString()))
                .andExpect(jsonPath("$.count").value(1))
                .andExpect(jsonPath("$.from").value(T_HOLD.toString()))
                .andExpect(jsonPath("$.to").value(T_HOLD_2.toString()))
                .andExpect(jsonPath("$.items[0].bagTag").value("BAG1"));
        mockMvc.perform(get("/api/claim-holds").param("from", T_HOLD_2.toString()))
                .andExpect(jsonPath("$.count").value(1))
                .andExpect(jsonPath("$.items[0].bagTag").value("BAG2"));
        mockMvc.perform(get("/api/claim-holds").param("to", T_HOLD.toString()))
                .andExpect(jsonPath("$.count").value(0))
                .andExpect(jsonPath("$.items", hasSize(0)));
        mockMvc.perform(get("/api/claim-holds").param("status", "ACTIVE"))
                .andExpect(jsonPath("$.count").value(2));
        mockMvc.perform(get("/api/claim-holds").param("status", "RELEASED"))
                .andExpect(jsonPath("$.count").value(0));

        // 非法过滤条件 -> 400
        mockMvc.perform(get("/api/claim-holds").param("status", "BOGUS"))
                .andExpect(status().isBadRequest());
