package com.example.starter.baggage;

import java.util.ArrayList;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.Callable;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.Future;
import java.util.concurrent.TimeUnit;

import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;

import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldRequest;
import com.example.starter.baggage.ClaimHoldDtos.ClaimHoldResponse;
import com.example.starter.baggage.BaggageDtos.LoadRequest;
import com.example.starter.baggage.BaggageDtos.LoadResponse;
import com.example.starter.baggage.BaggageDtos.RegisterBagRequest;
import com.example.starter.baggage.BaggageDtos.RegisterLegRequest;
import com.example.starter.baggage.BaggageDtos.SealRequest;
import com.example.starter.baggage.BaggageDtos.SealResponse;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * 认领冻结并发边界测试：同一行李并发冻结只有一个生效；
 * 冻结与封舱、冻结与装载按提交顺序裁决；同键并发重放只生效一次。
 * 全部基于 H2 MySQL 兼容模式真实数据库与真实并发，不使用 mock。
 */
@SpringBootTest
class ClaimHoldConcurrencyTest {

    @Autowired
    private BaggageService baggageService;

    @Autowired
    private ClaimHoldService claimHoldService;

    @Autowired
    private JdbcTemplate jdbcTemplate;

    private ExecutorService executor;

    @BeforeEach
    void setUp() {
        jdbcTemplate.update("DELETE FROM claim_hold_chain");
        jdbcTemplate.update("DELETE FROM claim_hold");
        jdbcTemplate.update("DELETE FROM bag_event");
        jdbcTemplate.update("DELETE FROM load_record");
        jdbcTemplate.update("DELETE FROM bag_itinerary");
        jdbcTemplate.update("DELETE FROM bag");
        jdbcTemplate.update("DELETE FROM leg");
        jdbcTemplate.update("DELETE FROM request_log");
        executor = Executors.newFixedThreadPool(8);
    }

    @AfterEach
    void tearDown() throws InterruptedException {
        executor.shutdownNow();
        assertThat(executor.awaitTermination(10, TimeUnit.SECONDS)).isTrue();
    }

    @Test
    void concurrentFreezeSameBag_onlyOneActiveHold() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));

        List<Callable<Object>> tasks = new ArrayList<>();
        for (int i = 0; i < 4; i++) {
            int index = i;
            tasks.add(() -> claimHoldService.freeze(new ClaimHoldRequest(
                    UUID.randomUUID().toString(), "BAG1", "CLAIM-" + index,
                    "DIGEST", "原因", "CS_" + index)));
        }
        List<Object> results = runConcurrently(tasks);

        long successes = results.stream().filter(ClaimHoldResponse.class::isInstance).count();
        long conflicts = results.stream()
                .filter(ApiException.class::isInstance)
                .map(ApiException.class::cast)
                .filter(ex -> ex.getStatus().value() == 409)
                .count();
        assertThat(successes).isEqualTo(1);
        assertThat(conflicts).isEqualTo(3);

        Integer holds = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM claim_hold WHERE bag_tag = 'BAG1'", Integer.class);
        assertThat(holds).isEqualTo(1);
        String status = jdbcTemplate.queryForObject(
                "SELECT status FROM bag WHERE bag_tag = 'BAG1'", String.class);
        assertThat(status).isEqualTo("CLAIM_HOLD");
    }

    @Test
    void concurrentFreezeAndSeal_submissionOrderDecides() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));
        baggageService.load("LEG1", new LoadRequest(UUID.randomUUID().toString(), 1, List.of("BAG1")));

        List<Callable<Object>> tasks = List.of(
                () -> baggageService.seal("LEG1", new SealRequest(UUID.randomUUID().toString(), 2)),
                () -> claimHoldService.freeze(new ClaimHoldRequest(
                        UUID.randomUUID().toString(), "BAG1", "CLAIM-1", "DIGEST", "原因", "CS_A")));
        List<Object> results = runConcurrently(tasks);

        boolean sealed = results.stream().anyMatch(SealResponse.class::isInstance);
        boolean frozen = results.stream().anyMatch(ClaimHoldResponse.class::isInstance);
        // 按提交顺序裁决：封舱先提交则冻结 409，冻结先提交则封舱版本冲突 409，恰有一个成功
        assertThat(sealed).isNotEqualTo(frozen);
        long conflicts = results.stream()
                .filter(ApiException.class::isInstance)
                .map(ApiException.class::cast)
                .filter(ex -> ex.getStatus().value() == 409)
                .count();
        assertThat(conflicts).isEqualTo(1);

        String legStatus = jdbcTemplate.queryForObject(
                "SELECT status FROM leg WHERE leg_id = 'LEG1'", String.class);
        String bagStatus = jdbcTemplate.queryForObject(
                "SELECT status FROM bag WHERE bag_tag = 'BAG1'", String.class);
        Integer loadRecords = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
        if (sealed) {
            // 封舱先提交：行李留在封舱清单，冻结被拒绝
            assertThat(legStatus).isEqualTo("SEALED");
            assertThat(bagStatus).isEqualTo("IN_TRANSIT");
            assertThat(loadRecords).isEqualTo(1);
            assertThat(countRows("claim_hold")).isZero();
        } else {
            // 冻结先提交：行李移出清单并转 CLAIM_HOLD，封舱因版本冲突失败
            assertThat(legStatus).isEqualTo("OPEN");
            assertThat(bagStatus).isEqualTo("CLAIM_HOLD");
            assertThat(loadRecords).isZero();
            assertThat(countRows("claim_hold")).isEqualTo(1);
        }
    }

    @Test
    void concurrentFreezeAndLoad_consistentFinalState() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));

        List<Callable<Object>> tasks = List.of(
                () -> baggageService.load("LEG1",
                        new LoadRequest(UUID.randomUUID().toString(), 1, List.of("BAG1"))),
                () -> claimHoldService.freeze(new ClaimHoldRequest(
                        UUID.randomUUID().toString(), "BAG1", "CLAIM-1", "DIGEST", "原因", "CS_A")));
        List<Object> results = runConcurrently(tasks);

        boolean loaded = results.stream().anyMatch(LoadResponse.class::isInstance);
        boolean frozen = results.stream().anyMatch(ClaimHoldResponse.class::isInstance);
        // 冻结总是成功；装载先提交则冻结将其移出清单，冻结先提交则装载 409
        assertThat(frozen).isTrue();
        if (!loaded) {
            long conflicts = results.stream()
                    .filter(ApiException.class::isInstance)
                    .map(ApiException.class::cast)
                    .filter(ex -> ex.getStatus().value() == 409)
                    .count();
            assertThat(conflicts).isEqualTo(1);
        }
        // 最终状态一致：行李 CLAIM_HOLD 且不在任何清单中
        String bagStatus = jdbcTemplate.queryForObject(
                "SELECT status FROM bag WHERE bag_tag = 'BAG1'", String.class);
        assertThat(bagStatus).isEqualTo("CLAIM_HOLD");
        Integer loadRecords = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
        assertThat(loadRecords).isZero();
        assertThat(countRows("claim_hold")).isEqualTo(1);
    }

    @Test
    void concurrentSameRequestIdFreeze_replaysSingleEffect() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));

        String requestId = UUID.randomUUID().toString();
        List<Callable<Object>> tasks = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            tasks.add(() -> claimHoldService.freeze(new ClaimHoldRequest(
                    requestId, "BAG1", "CLAIM-1", "DIGEST", "原因", "CS_A")));
        }
        List<Object> results = runConcurrently(tasks);

        assertThat(results).allSatisfy(result -> assertThat(result)
                .isInstanceOf(ClaimHoldResponse.class));
        String holdId = ((ClaimHoldResponse) results.get(0)).holdId();
        assertThat(results).allSatisfy(result ->
                assertThat(((ClaimHoldResponse) result).holdId()).isEqualTo(holdId));
        assertThat(countRows("claim_hold")).isEqualTo(1);
        assertThat(countRows("claim_hold_chain")).isEqualTo(1);
        Integer logs = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM request_log WHERE request_id = ?", Integer.class, requestId);
        assertThat(logs).isEqualTo(1);
    }

    private int countRows(String table) {
        Integer count = jdbcTemplate.queryForObject("SELECT COUNT(*) FROM " + table, Integer.class);
        return count == null ? 0 : count;
    }

    private void registerLeg(String legId, String origin, String destination) {
        baggageService.registerLeg(
                new RegisterLegRequest(UUID.randomUUID().toString(), legId, origin, destination));
    }

    private void registerBag(String bagTag, List<String> legIds) {
        baggageService.registerBag(new RegisterBagRequest(UUID.randomUUID().toString(), bagTag, legIds));
    }

    /** 同步起跑并发执行任务，结果按提交顺序返回（异常包装为返回值）。 */
    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
        CountDownLatch ready = new CountDownLatch(tasks.size());
        CountDownLatch start = new CountDownLatch(1);
        List<Future<Object>> futures = new ArrayList<>();
        for (Callable<Object> task : tasks) {
            futures.add(executor.submit(() -> {
                ready.countDown();
                assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
                try {
                    return task.call();
                } catch (ApiException ex) {
                    return ex;
                }
            }));
        }
        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
        start.countDown();
        List<Object> results = new ArrayList<>();
        for (Future<Object> future : futures) {
            results.add(future.get(30, TimeUnit.SECONDS));
        }
        return results;
    }
}

