            // 封舱先提交：行李留在封舱清单，冻结被拒绝
            assertThat(legStatus).isEqualTo("SEALED");
            assertThat(bagStatus).isEqualTo("IN_TRANSIT");
            assertThat(loadRecords).isEqualTo(1);
            assertThat(countRows("claim_hold")).isZero();
        } else {
            // 冻结先提交：行李移出清单并转 CLAIM_HOLD，封舱因版本冲突失败
            assertThat(legStatus).isEqualTo("OPEN");
            assertThat(bagStatus).isEqualTo("CLAIM_HOLD");
            assertThat(loadRecords).isZero();
            assertThat(countRows("claim_hold")).isEqualTo(1);
        }
    }

    @Test
    void concurrentFreezeAndLoad_consistentFinalState() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));

        List<Callable<Object>> tasks = List.of(
                () -> baggageService.load("LEG1",
                        new LoadRequest(UUID.randomUUID().toString(), 1, List.of("BAG1"))),
                () -> claimHoldService.freeze(new ClaimHoldRequest(
                        UUID.randomUUID().toString(), "BAG1", "CLAIM-1", "DIGEST", "原因", "CS_A")));
        List<Object> results = runConcurrently(tasks);

        boolean loaded = results.stream().anyMatch(LoadResponse.class::isInstance);
        boolean frozen = results.stream().anyMatch(ClaimHoldResponse.class::isInstance);
        // 冻结总是成功；装载先提交则冻结将其移出清单，冻结先提交则装载 409
        assertThat(frozen).isTrue();
        if (!loaded) {
            long conflicts = results.stream()
                    .filter(ApiException.class::isInstance)
                    .map(ApiException.class::cast)
                    .filter(ex -> ex.getStatus().value() == 409)
                    .count();
            assertThat(conflicts).isEqualTo(1);
        }
        // 最终状态一致：行李 CLAIM_HOLD 且不在任何清单中
        String bagStatus = jdbcTemplate.queryForObject(
                "SELECT status FROM bag WHERE bag_tag = 'BAG1'", String.class);
        assertThat(bagStatus).isEqualTo("CLAIM_HOLD");
        Integer loadRecords = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM load_record WHERE bag_tag = 'BAG1'", Integer.class);
        assertThat(loadRecords).isZero();
        assertThat(countRows("claim_hold")).isEqualTo(1);
    }

    @Test
    void concurrentSameRequestIdFreeze_replaysSingleEffect() throws Exception {
        registerLeg("LEG1", "PEK", "SHA");
        registerBag("BAG1", List.of("LEG1"));

        String requestId = UUID.randomUUID().toString();
        List<Callable<Object>> tasks = new ArrayList<>();
        for (int i = 0; i < 6; i++) {
            tasks.add(() -> claimHoldService.freeze(new ClaimHoldRequest(
                    requestId, "BAG1", "CLAIM-1", "DIGEST", "原因", "CS_A")));
        }
        List<Object> results = runConcurrently(tasks);

        assertThat(results).allSatisfy(result -> assertThat(result)
                .isInstanceOf(ClaimHoldResponse.class));
        String holdId = ((ClaimHoldResponse) results.get(0)).holdId();
        assertThat(results).allSatisfy(result ->
                assertThat(((ClaimHoldResponse) result).holdId()).isEqualTo(holdId));
        assertThat(countRows("claim_hold")).isEqualTo(1);
        assertThat(countRows("claim_hold_chain")).isEqualTo(1);
        Integer logs = jdbcTemplate.queryForObject(
                "SELECT COUNT(*) FROM request_log WHERE request_id = ?", Integer.class, requestId);
        assertThat(logs).isEqualTo(1);
    }

    private int countRows(String table) {
        Integer count = jdbcTemplate.queryForObject("SELECT COUNT(*) FROM " + table, Integer.class);
        return count == null ? 0 : count;
    }

    private void registerLeg(String legId, String origin, String destination) {
        baggageService.registerLeg(
                new RegisterLegRequest(UUID.randomUUID().toString(), legId, origin, destination));
    }

    private void registerBag(String bagTag, List<String> legIds) {
        baggageService.registerBag(new RegisterBagRequest(UUID.randomUUID().toString(), bagTag, legIds));
    }

    /** 同步起跑并发执行任务，结果按提交顺序返回（异常包装为返回值）。 */
    private List<Object> runConcurrently(List<Callable<Object>> tasks) throws Exception {
        CountDownLatch ready = new CountDownLatch(tasks.size());
        CountDownLatch start = new CountDownLatch(1);
        List<Future<Object>> futures = new ArrayList<>();
        for (Callable<Object> task : tasks) {
            futures.add(executor.submit(() -> {
                ready.countDown();
                assertThat(start.await(10, TimeUnit.SECONDS)).isTrue();
                try {
                    return task.call();
                } catch (ApiException ex) {
                    return ex;
                }
            }));
        }
        assertThat(ready.await(10, TimeUnit.SECONDS)).isTrue();
        start.countDown();
        List<Object> results = new ArrayList<>();
        for (Future<Object> future : futures) {
            results.add(future.get(30, TimeUnit.SECONDS));
        }
        return results;
    }
}

